import type { DesktopManifest } from "./desktopContract";

/** Fixed, reviewed portable runner template. No model-generated source is interpolated. */
export function renderRobotScript(manifest: DesktopManifest): string {
  return `"use strict";
/* Generated by RASQ-Ai ${manifest.compilerVersion} from ${manifest.rasqDesktopVersion}.
 * Default mode is dry-run. Real input requires --attended --yes and an isolated desktop.
 * This portable runner does not verify/focus the OS window; use the RASQ-Ai agent for that control.
 */
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const robot = require("robotjs");
const manifest = ${JSON.stringify(manifest, null, 2)};
const args = process.argv.slice(2);
const attended = args.includes("--attended");
if (attended && !args.includes("--yes")) throw new Error("Attended execution also requires --yes after reviewing the target and bundle.");
const displayArg = args.indexOf("--display");
const targetArg = args.indexOf("--target-title");
const displayId = displayArg >= 0 ? args[displayArg + 1] : manifest.target.displayId;
const expectedTitle = targetArg >= 0 ? args[targetArg + 1] : manifest.target.windowTitle;
if (attended && !expectedTitle) throw new Error("Supply --target-title with the window you manually opened and focused.");
const root = __dirname;
const evidenceDir = path.join(root, "rasq-desktop-evidence");
fs.mkdirSync(evidenceDir, { recursive: true });
const displays = robot.getDisplays();
const display = displays.find((d) => String(d.id) === String(displayId)) || (!displayId ? displays.find((d) => d.isMain) : null);
if (!display) throw new Error("The selected display is not available; no input was dispatched.");
if (!robot.image.supportsPNG) throw new Error("This RobotJS build lacks PNG support required by RASQ-Ai anchor bundles.");
robot.setMouseDelay(10);
robot.setKeyboardDelay(10);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, Math.min(10000, Math.max(0, ms))));
const digest = (b) => crypto.createHash("sha256").update(b).digest("hex");
let sequence = 0;
let previousBefore = null;
let actionStarted = 0;
let needsReview = 0;
const summary = { passed: 0, failed: 0, skipped: 0, "needs-review": 0 };
function capture() {
  const image = robot.screen.capture(display.x, display.y, display.width, display.height);
  const file = path.join(evidenceDir, String(++sequence).padStart(4, "0") + ".png");
  image.save(file);
  const png = fs.readFileSync(file);
  return { image, png, file, sha256: digest(png) };
}
function locate(frame, anchor) {
  const asset = path.join(root, anchor.asset);
  if (!asset.startsWith(path.join(root, "anchors") + path.sep)) throw new Error("Unsafe anchor path.");
  const needle = robot.image.load(asset);
  const matches = frame.image.findImages(needle, { tolerance: anchor.tolerance });
  if (matches.length !== 1) throw new Error("Strict anchor validation found " + matches.length + " matches for control " + anchor.controlId + "; no input dispatched.");
  return { match: matches[0], needle };
}
function move(frame, found, fraction = 0.5) {
  const point = frame.image.toScreenPoint({ x: found.match.x + Math.floor(found.needle.width * fraction), y: found.match.y + Math.floor(found.needle.height / 2) });
  robot.moveMouseSmooth(point.x, point.y);
}
function click(frame, found, fraction = 0.5) {
  move(frame, found, fraction);
  robot.mouseClick("left");
}
function record(step, status, message, extra = {}) {
  summary[status] = (summary[status] || 0) + 1;
  const event = { nodeId: step.nodeId, status, message, ...extra };
  fs.writeFileSync(path.join(evidenceDir, String(step.position).padStart(4, "0") + "-result.json"), JSON.stringify(event, null, 2));
  console.log(JSON.stringify(event));
}
async function main() {
  console.log(JSON.stringify({ contract: manifest.rasqDesktopVersion, bundleId: manifest.bundleId, mode: attended ? "attended" : "dry-run", expectedTitle }));
  for (const step of manifest.steps) {
    const started = Date.now();
    if (step.kind !== "action" && step.kind !== "assert") {
      record(step, "passed", step.kind === "target" ? "Portable target step: operator must manually open/focus " + expectedTitle + "." : step.kind === "section" ? "Test case section." : "Run started.");
      continue;
    }
    if (step.kind === "assert") {
      if (step.assertion === "manualReview") {
        needsReview += 1;
        record(step, "needs-review", "Human verification required: " + step.expected);
        continue;
      }
      const deadline = Date.now() + (step.maxDurationMs || 1500);
      let changed = false;
      let elapsed = 0;
      do {
        const now = capture();
        elapsed = Date.now() - actionStarted;
        changed = Boolean(previousBefore && digest(now.png) !== previousBefore);
        if (changed) break;
        if (Date.now() >= deadline) break;
        await sleep(100);
      } while (true);
      if (!changed) {
        record(step, "failed", "No visual transition was observed within the assertion deadline.", { elapsedMs: elapsed });
        throw new Error("Visual assertion failed; execution stopped.");
      }
      if (step.maxDurationMs !== null && elapsed > step.maxDurationMs) {
        record(step, "failed", "Visual transition exceeded the configured deadline.", { elapsedMs: elapsed });
        throw new Error("Visual timing assertion failed; execution stopped.");
      }
      record(step, "passed", "Pixels changed; exact business content was not verified.", { elapsedMs: elapsed });
      continue;
    }
    if (step.action === "navigate") {
      record(step, attended ? "passed" : "skipped", attended ? "Operator confirmed the application window; portable runner cannot verify focus." : "Dry run: no target focus or input performed.");
      continue;
    }
    if (step.action === "wait") {
      if (attended) await sleep(Number(step.data || 500));
      record(step, attended ? "passed" : "skipped", attended ? "Wait completed." : "Dry run: wait validated only.");
      continue;
    }
    if (!step.anchor) throw new Error("Action has no anchor; no input dispatched.");
    const before = capture();
    const found = locate(before, step.anchor);
    if (!attended) {
      record(step, "skipped", "Dry run: exactly one visual anchor observed; no input dispatched.", { controlId: step.anchor.controlId, beforeSha256: before.sha256 });
      continue;
    }
    previousBefore = before.sha256;
    actionStarted = Date.now();
    const value = step.action === "type" ? (step.secretRef ? process.env[step.secretRef] : step.data || "") : "";
    if (step.action === "type" && step.secretRef && !value) throw new Error("Secret environment variable is empty; no click or text input was dispatched.");
    const timedEvidence = {};
    if (step.action === "hold") {
      const durationMs = Number(step.data || 1000);
      move(before, found);
      robot.mouseToggle("down", "left");
      try { await sleep(durationMs); } finally { robot.mouseToggle("up", "left"); }
      timedEvidence.holdMs = durationMs;
    } else if (step.action === "hover") {
      const durationMs = Number(step.data || 1000);
      move(before, found);
      await sleep(durationMs);
      timedEvidence.hoverMs = durationMs;
    } else if (step.action === "slider") {
      click(before, found, Math.max(0, Math.min(1, Number(step.data || 50) / 100)));
    } else {
      click(before, found);
    }
    if (step.action === "type") {
      robot.keyTap("a", process.platform === "darwin" ? "command" : "control");
      robot.typeString(value);
    } else if (step.action === "select") {
      if (step.data && step.data !== "first option") robot.typeString(step.data);
      else robot.keyTap("down");
      robot.keyTap("enter");
    }
    const after = capture();
    const evidence = { controlId: step.anchor.controlId, beforeSha256: before.sha256, afterSha256: after.sha256, regionChanged: before.sha256 !== after.sha256, ...timedEvidence };
    record(step, "passed", step.action + " dispatched after one strict anchor match; this is not business-success evidence.", evidence);
  }
  const status = summary.failed ? "failed" : needsReview ? "needs-review" : attended ? "passed" : "skipped";
  console.log(JSON.stringify({ status, summary, evidenceDir }));
  if (status === "failed") process.exitCode = 1;
}
main().catch((error) => {
  try { robot.keyToggle("control", "up"); robot.keyToggle("shift", "up"); robot.keyToggle("alt", "up"); robot.mouseToggle("up", "left"); } catch {}
  console.error(JSON.stringify({ status: "error", message: error instanceof Error ? error.message : String(error) }));
  process.exitCode = 1;
});
`;
}
